"""Generate JVM bindings from the reviewed framing/semantic tables (no game execution)."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent

def generate():
    framing = {p['id']: p for p in json.loads((ROOT/'profiles/dc123.json').read_text(encoding='utf-8'))['profiles']}
    semantics = json.loads((ROOT/'profiles/mes-semantics.json').read_text(encoding='utf-8'))['profiles']
    lines = ['package org.circus.core;', 'import java.util.*;',
             '// Generated by tools/generate_runtime_profiles.py; do not edit.',
             'public final class Profiles {', 'private Profiles() {}',
             'public static Profile get(String id) { Map<Integer,String> ops=new HashMap<>();']
    for pid, s in semantics.items():
        f = framing[pid]; starts = {kind: a for kind,a,b in f['ranges']}; c=s['control']
        lines.append('if(id.equals('+json.dumps(pid)+')) {')
        for op, semantic in s['opcodes'].items():
            lines.append(f'ops.put({int(op,16)}, {json.dumps(semantic)});')
        mapping=s['decoder'].get('encoded_string_postmap')
        model=s.get('runtime_variable_model','BYTE_WRAP')
        if model not in ('BYTE_WRAP','DC2_PACKED','PC_BYTE','PC_WIDE'): raise ValueError('Unknown variable model: '+model)
        stride=6 if f['layout']=='offset2' else 4
        marker=s['decoder'].get('version_bytes',3 if stride==6 else 2)
        fields=[json.dumps(pid),str(f['version']),str(stride),str(marker),str(starts.get('u8str',starts['string'])),str(starts['string']),str(starts['encoded_string']),str(starts['u16x4']),str(s['decoder']['extension_opcode']),str(c['label_opcode']),str(c['block_marker_opcode']),str(c['companion_opcode']),str(c['block_scan_signed_opcode']).lower(),str(mapping == {'36':32}).lower(),str(mapping is not None).lower(),'false','Variables.Model.'+model,'ops']
        lines += ['return new Profile('+','.join(fields)+');','}']
    lines += ['if(id.equals("circus-demo-v1")) {',
              'Profile dd=get("dc3dd-a5a8"); for(int i=0;i<256;i++)if(!dd.operation(i).equals("unknown"))ops.put(i,dd.operation(i));',
              'ops.put(0x44,"demo.scene"); ops.put(0x45,"demo.text"); ops.put(0x46,"demo.audio");',
              'ops.put(0x68,"demo.wait_click"); ops.put(0x69,"demo.wait_choice"); ops.put(0x6a,"demo.delay");',
              'return new Profile(id,0xdca0,6,3,0x39,0x44,0x63,0x68,0x71,0x47,0x1f,2,false,true,true,ops);',
              '}', 'throw new IllegalArgumentException("Unverified runtime profile: "+id);', '}', '}']
    target=ROOT/'runtime/core/src/org/circus/core/Profiles.java';target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    formats=['package org.circus.core;', '// Generated from profiles/dc123.json; framing does not imply execution support.',
             'final class MesFormats {', 'static final class Format { final String id; final int version,stride;',
             'Format(String id,int version,int stride){this.id=id;this.version=version;this.stride=stride;} }',
             'static final Format[] ALL={']
    for pid,f in framing.items(): formats.append('new Format('+json.dumps(pid)+','+str(f['version'])+','+('6' if f['layout']=='offset2' else '4')+'),')
    formats+=['};','private MesFormats(){}','}']
    (target.parent/'MesFormats.java').write_text('\n'.join(formats)+'\n',encoding='utf-8')

if __name__=='__main__': generate()
